class HomeView extends ConsumerStatefulWidget {
  const HomeView({super.key});

  static const routeName = "/home";

  @override
  ConsumerState<HomeView> createState() => _HomeViewState();
}

class _HomeViewState extends ConsumerState<HomeView> {
  final GlobalKey<ScaffoldState> _key = GlobalKey<ScaffoldState>();

  // keep reference to be able to remove listener in dispose without requiring the riverpod ref
  late final Prefs _prefs;

  late final PageController _pageController;
  late final RotateIconController _rotateIconController;

  late final List<Widget> _children;

  DateTime? _cachedTime;

  bool _exitEnabled = false;

  IdleMonitor? _idleMonitor;

  /// The idle lock screen is up: payment links wait for the unlock.
  bool _locked = false;
  bool _openingLink = false;

  Future<void> _openPendingLink() async {
    if (_locked || _openingLink || !mounted) return;
    final link = ref.read(pPendingPaymentLink);
    if (link == null) return;
    ref.read(pPendingPaymentLink.notifier).state = null;
    _openingLink = true;
    try {
      await openPaymentLink(context, ref, link);
    } finally {
      _openingLink = false;
    }
  }

  void _onIdle() async {
    final context = _key.currentContext;
    // Already locked: the timer runs on behind the lock screen.
    if (context != null && !_locked) {
      _locked = true;
      await Navigator.push(
        context,
        RouteGenerator.getRoute(
          shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
          builder: (_) => const LockscreenView(
            showBackButton: false,
            popOnSuccess: true,
            routeOnSuccessArguments: true,
            routeOnSuccess: "",
            biometricsCancelButtonString: "CANCEL",
            biometricsLocalizedReason:
                "Authenticate to unlock ${AppConfig.appName}",
            biometricsAuthenticationTitle: "Unlock ${AppConfig.appName}",
          ),
          settings: const RouteSettings(name: "/unlockTimedOutAppScreen"),
        ),
      );
      _locked = false;
      unawaited(_openPendingLink());
    }
  }

  late AutoLockInfo _autoLockInfo;
  void _prefsTimeoutListener() {
    final prefs = ref.read(prefsChangeNotifierProvider);
    if (mounted && prefs.autoLockInfo != _autoLockInfo) {
      _autoLockInfo = prefs.autoLockInfo;
      if (_autoLockInfo.enabled) {
        _idleMonitor?.detach();
        _idleMonitor = IdleMonitor(
          timeout: Duration(minutes: _autoLockInfo.minutes),
          onIdle: _onIdle,
        );
        _idleMonitor!.attach();
      } else {
        _idleMonitor?.detach();
        _idleMonitor = null;
      }
    }
  }

  Future<bool> _onWillPop() async {
    // Back from another tab returns to the wallets first.
    if (ref.read(homeViewPageIndexStateProvider) != 0) {
      ref.read(homeViewPageIndexStateProvider.notifier).state = 0;
      return false;
    }

    if (_exitEnabled) {
      _exitEnabled = false;
      return true;
    }

    final now = DateTime.now();
    const timeout = Duration(milliseconds: 1500);
    if (_cachedTime == null || now.difference(_cachedTime!) > timeout) {
      _cachedTime = now;
      await showDialog<dynamic>(
        context: context,
        barrierDismissible: false,
        builder: (_) => PopScope(
          // A back gesture closes it with no result: exit. The timeout
          // closes it with false.
          onPopInvokedWithResult: (didPop, result) {
            if (didPop && result != false) _exitEnabled = true;
          },
          child: const StackDialog(title: "Tap back again to exit"),
        ),
      ).timeout(
        timeout,
        onTimeout: () {
          _exitEnabled = false;
          if (mounted) Navigator.of(context).pop(false);
        },
      );
    }
    final exit = _exitEnabled;
    _exitEnabled = false;
    return exit;
  }

  bool _lock = false;

  Future<void> _animateToPage(int index) async {
    await _pageController.animateToPage(
      index,
      duration: const Duration(milliseconds: 300),
      curve: Curves.decelerate,
    );
  }

  Future<void> precacheSettingsIcons(BuildContext context) async {
    if (Util.isDesktop) return;

    final icons = [
      Assets.svg.addressBook,
      Assets.svg.downloadFolder,
      Assets.svg.lock,
      Assets.svg.dollarSign,
      Assets.svg.language,
      Assets.svg.node,
      Assets.svg.arrowRotate,
      Assets.svg.arrowUpRight,
      Assets.svg.sun,
      Assets.svg.circleAlert,
      Assets.svg.ellipsis,
      Assets.svg.solidSliders,
      Assets.svg.questionMessage,
    ];

    for (final asset in icons) {
      final loader = SvgAssetLoader(asset);
      await svg.cache.putIfAbsent(
        loader.cacheKey(context),
        () => loader.loadBytes(context),
      );
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();

    precacheSettingsIcons(context);
  }

  @override
  void initState() {
    _prefs = ref.read(prefsChangeNotifierProvider);
    _autoLockInfo = ref.read(prefsChangeNotifierProvider).autoLockInfo;
    if (_autoLockInfo.enabled) {
      _idleMonitor = IdleMonitor(
        timeout: Duration(minutes: _autoLockInfo.minutes),
        onIdle: _onIdle,
      );
    }

    _pageController = PageController();
    _rotateIconController = RotateIconController();
    _children = [const WalletsView()];

    _idleMonitor?.attach();

    ref.read(prefsChangeNotifierProvider).addListener(_prefsTimeoutListener);

    // A link that opened the app: after the start-up wallet (if any) is
    // on screen.
    WidgetsBinding.instance.addPostFrameCallback(
      (_) => Future<void>.delayed(
        const Duration(milliseconds: 700),
        _openPendingLink,
      ),
    );

    super.initState();
  }

  @override
  dispose() {
    _prefs.removeListener(_prefsTimeoutListener);
    _idleMonitor?.detach();
    _pageController.dispose();
    _rotateIconController.forward = null;
    _rotateIconController.reverse = null;
    _rotateIconController.reset = null;
    super.dispose();
  }

  DateTime _hiddenTime = DateTime.now();
  int _hiddenCount = 0;

  void _hiddenOptions() {
    _rotateIconController.reset?.call();
    _rotateIconController.forward?.call();
    if (_hiddenCount == 5) {
      Navigator.of(context).pushNamed(HiddenSettings.routeName);
    }
    final now = DateTime.now();
    const timeout = Duration(seconds: 1);
    if (now.difference(_hiddenTime) < timeout) {
      _hiddenCount++;
    } else {
      _hiddenCount = 0;
    }
    _hiddenTime = now;
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");
    ref.listen(pPendingPaymentLink, (_, next) {
      if (next != null) unawaited(_openPendingLink());
    });

    // PopScope, not WillPopScope: Android 16+ (predictive back) only
    // hands the back gesture to the app when it says it handles it.
    // Otherwise the first back on this root screen closes the app.
    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (didPop, _) async {
        if (didPop) return;
        if (await _onWillPop()) await SystemNavigator.pop();
      },
      child: Background(
        child: Scaffold(
          backgroundColor: Colors.transparent,
          key: _key,
          appBar: AppBar(
            automaticallyImplyLeading: false,
            backgroundColor: Theme.of(context)
                .extension<StackColors>()!
                .backgroundAppBar,
            title: Row(
              children: [
                GestureDetector(
                  onTap: _hiddenOptions,
                  child: RotateIcon(
                    icon: const AppIcon(width: 24, height: 24),
                    curve: Curves.easeInOutCubic,
                    rotationPercent: 1.0,
                    controller: _rotateIconController,
                  ),
                ),
                const SizedBox(width: 16),
                Text(AppConfig.prefix, style: STextStyles.navBarTitle(context)),
              ],
            ),
            actions: [
              if (AppConfig.hasFeature(AppFeature.tor))
                const Padding(
                  padding: EdgeInsets.only(top: 10, bottom: 10, right: 10),
                  child: AspectRatio(aspectRatio: 1, child: SmallTorIcon()),
                ),
              Padding(
                padding: const EdgeInsets.only(top: 10, bottom: 10, right: 10),
                child: AspectRatio(
                  aspectRatio: 1,
                  child: AppBarIconButton(
                    semanticsLabel: "Settings Button. Takes To Settings Page.",
                    key: const Key("walletsViewSettingsButton"),
                    size: 36,
                    shadows: const [],
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .backgroundAppBar,
                    icon: SvgPicture.asset(
                      Assets.svg.gear,
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .topNavIconPrimary,
                      width: 20,
                      height: 20,
                    ),
                    onPressed: () {
                      Navigator.of(context)
                          .pushNamed(GlobalSettingsView.routeName);
                    },
                  ),
                ),
              ),
            ],
          ),
          body: SafeArea(
            child: Column(
              children: [
                Expanded(
                  child: Consumer(
                    builder: (_, _ref, __) {
                      _ref.listen(homeViewPageIndexStateProvider, (
                        previous,
                        next,
                      ) {
                        if (next >= 0 && next < _children.length) {
                          _lock = true;
                          _animateToPage(next).then((value) => _lock = false);
                        }
                      });
                      return PageView(
                        controller: _pageController,
                        children: _children,
                        onPageChanged: (pageIndex) {
                          if (!_lock) {
                            ref
                                    .read(
                                      homeViewPageIndexStateProvider.notifier,
                                    )
                                    .state =
                                pageIndex;
                          }
                        },
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
